-- Expand only: UUID PK/FKs and API contracts remain operational until cutover.
-- Hand-authored from the inspected 44-table production catalog; no data deletion.
set constraints all immediate;
set local lock_timeout = '5s';
set local statement_timeout = '120s';
-- Refuse an unreviewed schema baseline instead of guessing at changed write RPCs.
do $$ begin
 if (select md5(string_agg(table_name||'.'||column_name||':'||udt_name, ',' order by (table_name||'.'||column_name||':'||udt_name) collate "C")) from information_schema.columns where table_schema='public') <> '548bf9d1378e2956703b7f64391d3a69' then
  raise exception 'identifier_schema_drift: refresh the 44-table baseline and rehearse again';
 end if;
end $$;
-- Do not replace write RPCs whose business logic has changed since inspection.
do $$ begin
 if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_measurement_request' and md5(replace(p.prosrc,chr(13),''))='133e213250a60e520c8cfa39f343e441') <> 1 then raise exception 'identifier_rpc_drift: create_measurement_request'; end if;
 if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='notify_measurement_request' and md5(replace(p.prosrc,chr(13),''))='553613990c6b009175ec25e1318363e4') <> 1 then raise exception 'identifier_rpc_drift: notify_measurement_request'; end if;
end $$;
create schema if not exists private;
create schema if not exists review;
revoke all on schema review from public, anon, authenticated;
revoke all on schema private from public, anon, authenticated;
grant usage on schema review, private to service_role;
create table private.identifier_aliases (entity text not null, legacy_id uuid not null, numeric_id bigint not null, code text not null, primary key (entity, legacy_id), unique (entity, numeric_id), unique (code));
alter table private.identifier_aliases enable row level security;
revoke all on private.identifier_aliases from public, anon, authenticated;
grant select on private.identifier_aliases to service_role;
-- Preserve each trigger's enabled/replica/always/disabled state exactly.
create temporary table identifier_saved_triggers on commit drop as select n.nspname,c.relname,t.tgname,t.tgenabled from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal;
do $$ declare r record; begin for r in select distinct relname from identifier_saved_triggers loop execute format('alter table public.%I disable trigger user',r.relname); end loop; end $$;
alter table public.profiles add column numeric_id bigint;
with numbered as (select id, row_number() over (order by created_at nulls last, id) as n from public.profiles) update public.profiles t set numeric_id=n.n from numbered n where t.id=n.id;
alter table public.profiles alter column numeric_id set not null, alter column numeric_id add generated always as identity;
select setval(pg_get_serial_sequence('public.profiles','numeric_id'),coalesce(max(numeric_id),1),count(*)>0) from public.profiles;
alter table public.profiles add constraint profiles_numeric_id_key unique (numeric_id);
alter table public.profiles add column code text generated always as ('USR-' || lpad(numeric_id::text, greatest(6, length(numeric_id::text)), '0')) stored;
alter table public.profiles add constraint profiles_code_key unique (code);
insert into private.identifier_aliases select 'profiles',id,numeric_id,code from public.profiles;
