create function private.remember_identifier() returns trigger language plpgsql security definer set search_path='' as $$ declare old_number bigint; begin
 if tg_table_name='community_xp_accounts' then
  insert into private.identifier_aliases(entity,legacy_id,numeric_id,code) values('community_members',new.member_id,new.member_numeric_id,new.member_code) on conflict(entity,legacy_id) do nothing;
  select numeric_id into old_number from private.identifier_aliases where entity='community_members' and legacy_id=new.member_id;
  if old_number<>new.member_numeric_id then raise exception 'identifier_alias_reused'; end if;
 else
  insert into private.identifier_aliases(entity,legacy_id,numeric_id,code) values(tg_table_name,new.id,new.numeric_id,new.code) on conflict(entity,legacy_id) do nothing;
  select numeric_id into old_number from private.identifier_aliases where entity=tg_table_name and legacy_id=new.id;
  if old_number<>new.numeric_id then raise exception 'identifier_alias_reused'; end if;
 end if; return new; end $$;
revoke all on function private.remember_identifier() from public, anon, authenticated;
